import {icon,logo,avatar,badge,esc,money,statusLabel} from './ui.js';
import {mood} from './art.js';
import {providers} from './data.js';
const navigation=[['overview','grid','Overview'],['jobs','jobs','Broken jobs'],['market','network','The crew'],['receipts','receipt','Receipts'],['settings','settings','Settings']];
function walletBox(s){if(s.needsAuth)return `<div class="wallet-box"><strong>Wallet</strong><p>Sign in to send a rescue. The signature does not move USDC.</p><button type="button" class="btn btn-orange" data-action="sign-in">Sign in with wallet</button></div>`;const label=s.wallet?`${esc(s.wallet.slice(0,4))}…${esc(s.wallet.slice(-4))}`:'Signed in';return `<div class="wallet-box"><strong>Wallet</strong><small>${label}</small><button type="button" class="btn btn-outline" data-action="sign-out">Disconnect</button></div>`}
export function shell(s,path){const page=path[0]||'overview';let content='';if(page==='overview')content=overview(s);else if(page==='jobs'&&path[1])content=detail(s,path[1]);else if(page==='jobs')content=jobs(s);else if(page==='market')content=market(s);else if(page==='receipts'&&path[1])content=receipt(s,path[1]);else if(page==='receipts')content=receipts(s);else if(page==='settings')content=settings(s);else content=overview(s);
return `<div class="console"><aside class="sidebar" id="sidebar">${logo(true)}<button class="icon-btn sidebar-close" data-action="console-close" aria-label="Close console navigation">${icon('close')}</button><div class="workspace-picker"><span class="workspace-avatar">R</span><span>${esc(s.workspace||'My workspace')}<small>Live</small></span>${icon('down')}</div><div class="sidebar-label">WORKSPACE</div><nav class="sidebar-nav" aria-label="Console navigation">${navigation.map(([id,ic,label])=>`<a href="#/app/${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ic)}${label}${id==='jobs'?`<span>${s.jobs.filter(j=>j.status==='Needs rescue').length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-label">RESOURCES</div><nav class="sidebar-nav" aria-label="Project navigation"><a href="#/docs">${icon('book')}Documentation</a><a href="#/token">${icon('coins')}$RELAY community</a><a href="#/">${icon('globe')}Back to the website</a></nav><div class="sidebar-bottom">${s.jobs.some(j=>j.id==='RW-024')?`<div class="sidebar-promo">${mood('ready')}<strong>Gary broke something.</strong><p>Job RW-024 is stuck at 70%.<br>Patch is waiting.</p><a href="#/app/jobs/RW-024">Rescue it ${icon('right')}</a></div>`:''}${walletBox(s)}</div></aside><button class="console-scrim" data-action="console-close" aria-label="Close console navigation overlay"></button><div class="console-main"><header class="console-topbar"><div class="breadcrumbs"><button class="icon-btn console-mobile-menu" aria-label="Toggle console navigation" data-action="console-menu">${icon('menu')}</button><span>Workspace</span><span>/</span><strong>${navigation.find(n=>n[0]===page)?.[2]||'Overview'}${path[1]&&page==='jobs'?' / '+esc(path[1]):''}</strong></div><div class="topbar-actions">${s.needsAuth?`<button type="button" class="btn btn-orange wallet-top" data-action="sign-in">Sign in</button>`:`<button type="button" class="btn btn-outline wallet-top" data-action="sign-out">Disconnect${s.wallet?' '+esc(s.wallet.slice(0,4))+'…'+esc(s.wallet.slice(-4)):''}</button>`}<span class="sandbox-chip"><i></i> Live</span><a href="#/docs" class="icon-btn" aria-label="Open documentation">${icon('book')}</a></div></header><main id="main" class="console-content"><div class="console-demo-bar">${icon('info')}<span>${s.apiUnavailable?'Recovery service is unavailable. Reload to reconnect.':'Live. Accept the output first. USDC moves only when you pay.'}</span><a href="#/docs/status">What works today?</a></div>${content}<div class="console-footer"><span>${icon('shield')} ${'Your workspace stays in this browser'}</span><span>RelayWorks · Live</span></div></main></div></div>`}
function heading(eyebrow,title,description,action=true){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action?`<button class="btn btn-dark" data-action="new-job">${icon('plus')} New rescue</button>`:''}</div>`}
function stat(label,value,note,ic){return `<div class="stat-card"><div class="stat-card-top">${label}${icon(ic)}</div><div class="stat-value">${value}</div><div class="stat-card-bottom">${icon('dot')}${note}</div></div>`}
export function table(jobList,empty='No jobs match your search.'){return jobList.length?`<div class="table-scroll"><table class="job-list"><thead><tr><th>JOB / RECOVERY PACKAGE</th><th>PROGRESS</th><th>STATUS</th><th>BUDGET</th><th><span class="sr-only">Open</span></th></tr></thead><tbody>${jobList.map(j=>`<tr data-action="open-job" data-id="${esc(j.id)}"><td><div class="job-title-cell"><span class="mini-job-icon">${icon('file')}</span><div><a href="#/app/jobs/${encodeURIComponent(j.id)}"><strong>${esc(j.title)}</strong></a><small>${esc(j.id)} · ${esc(j.type)}</small></div></div></td><td data-label="Progress"><div class="table-progress"><span class="progress-track"><span style="width:${Math.round(j.completed/j.total*100)}%"></span></span>${Math.round(j.completed/j.total*100)}%</div></td><td data-label="Status">${badge(j.status)}</td><td class="table-amount" data-label="Budget">${money(j.budget)}<small>USDC cap</small></td><td><a href="#/app/jobs/${encodeURIComponent(j.id)}" aria-label="Open ${esc(j.title)}">${icon('arrow')}</a></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><div class="empty-art">${mood('sleep')}</div><h3>Nothing broken here.</h3><p>${empty}</p><button class="btn btn-outline btn-sm" data-action="new-job">${icon('plus')} Start a rescue</button></div>`}
function overview(s){const waiting=s.jobs.filter(j=>j.status==='Needs rescue').length;const ready=s.jobs.filter(j=>j.status==='Awaiting review').length;const verified=s.jobs.filter(j=>j.status==='Verified').length;const budget=s.jobs.reduce((a,j)=>a+(j.status!=='Cancelled'?j.budget:0),0);const spotlight=s.jobs.find(j=>j.status==='Needs rescue')||s.jobs[0];return `${heading('MISSION CONTROL','Gary broke a few things.','Everything your agents left half-done, in one place. Patch is standing by.')}<div class="stat-grid">${stat('Agents fainted',waiting,'Waiting for a fixer','jobs')}${stat('Check my work',ready,'Finished, needs your OK','shield')}${stat('Done, actually',verified,'Accepted or paid','check')}${stat('Budget caps',`${money(budget)} <small>USDC</small>`,'Spend caps','wallet')}</div><div class="dashboard-grid"><div class="panel"><div class="panel-heading"><div><h2>Broken jobs</h2><p>Newest disasters first.</p></div><a href="#/app/jobs">View all ${icon('right')}</a></div>${table(s.jobs.slice(0,5), s.jobs.length?'No jobs match your search.':'No rescues yet.')}</div>${spotlight?`<aside class="recovery-spotlight"><div class="spotlight-eyebrow"><span>MOST RESCUABLE</span>${icon('dot')}</div><div class="spotlight-art">${mood('ready')}</div><div class="progress-orbit"><svg viewBox="0 0 140 140" aria-hidden="true"><circle cx="70" cy="70" r="60" fill="none" stroke="#dce4cf" stroke-width="8"/><circle cx="70" cy="70" r="60" fill="none" stroke="#7e9865" stroke-width="8" stroke-dasharray="${Math.round(377*spotlight.completed/spotlight.total)} 377" stroke-linecap="round"/></svg><div><strong>${Math.round(spotlight.completed/spotlight.total*100)}<small style="display:inline;font-size:15px">%</small></strong><small>already complete</small></div></div><h3>${esc(spotlight.title)}</h3><p>Only ${spotlight.total-spotlight.completed} rows left.<br>The finished rows stay put.</p><a href="#/app/jobs/${spotlight.id}" class="btn btn-orange">Send in Patch ${icon('right')}</a><div class="spotlight-footnote">${icon('shield')} Budget capped at ${money(spotlight.budget)} USDC</div></aside>`:`<aside class="recovery-spotlight"><div class="spotlight-eyebrow"><span>MOST RESCUABLE</span>${icon('dot')}</div><div class="spotlight-art">${mood('ready')}</div><h3>Nothing in the queue.</h3><p>Sign in with your wallet, then send Patch the rows that are left.</p><button class="btn btn-orange" data-action="new-job">New rescue ${icon('right')}</button></aside>`}</div><div class="dashboard-lower"><section class="panel"><div class="panel-heading"><h2>What just happened</h2><span>Job log</span></div><div class="activity-list">${s.jobs.slice(0,3).map(j=>{const events=j.events||[];const ev=events[events.length-1];if(!ev)return '';return `<a href="#/app/jobs/${j.id}" class="activity-item"><span class="activity-symbol">${icon(ev.kind)}</span><div><strong>${esc(ev.label)}</strong><p>${esc(j.title)} · ${esc(ev.detail)}</p></div><span>${esc(j.created)}</span></a>`}).join('')}</div></section><section class="quick-start"><div class="eyebrow">GOT YOUR OWN MESS?</div><h3>Bring a broken job.<br>Leave with a plan.</h3><p>Use our sample package or paste your own JSON. Set a budget, pick a fixer, done.</p><button class="btn btn-outline btn-xs" data-action="new-job">${icon('upload')} Import a package</button></section></div>`}
function jobs(s){return `${heading('THE PILE','Broken jobs','Every job an agent started and didn’t finish. Search it, filter it, fix it.')}<div class="toolbar"><div class="filter-tabs" role="group" aria-label="Filter jobs">${['All jobs','Needs rescue','Recovering','Awaiting review','Accepted','Verified'].map(f=>`<button class="${s.jobFilter===f?'active':''}" data-action="job-filter" data-filter="${f}">${statusLabel(f)}<span>${f==='All jobs'?s.jobs.length:s.jobs.filter(j=>j.status===f).length}</span></button>`).join('')}</div><div class="search-field">${icon('search')}<input id="job-search" aria-label="Search recovery jobs" placeholder="Search jobs or IDs…" value="${esc(s.jobSearch||'')}"></div></div><div class="panel" id="jobs-table">${filteredTable(s)}</div>`}
export function filteredTable(s){return table(s.jobs.filter(j=>(s.jobFilter==='All jobs'||j.status===s.jobFilter)&&`${j.title} ${j.id}`.toLowerCase().includes((s.jobSearch||'').toLowerCase())))}
function market(s){let ps=providers.filter(p=>`${p.name} ${p.specialty} ${p.tags.join(' ')}`.toLowerCase().includes((s.providerSearch||'').toLowerCase()));if(s.providerSort==='price')ps.sort((a,b)=>a.price-b.price);return `${heading('THE CREW','Pick a fixer','Each fixer is good at one kind of mess. Compare quotes and pick one.',false)}<div class="toolbar"><div class="filter-tabs"><button class="active" data-action="market-all">All fixers <span>3</span></button><span class="sandbox-chip">Live crew</span></div><div style="display:flex;gap:10px"><div class="search-field">${icon('search')}<input id="provider-search" aria-label="Search providers" placeholder="Search skills or providers…" value="${esc(s.providerSearch||'')}"></div><select id="provider-sort" aria-label="Sort providers" style="font-size:10px;width:125px;padding:8px;border-radius:6px"><option value="recommended" ${s.providerSort!=='price'?'selected':''}>Recommended</option><option value="price" ${s.providerSort==='price'?'selected':''}>Lowest quote</option></select></div></div><div class="market-grid" id="market-results">${providerCards(ps,s)}</div><div class="market-note">${icon('info')}<span>Patch takes structured-data jobs. Atlas and Mender are on the crew and are not taking jobs yet.</span></div>`}
export function providerCards(ps,s){return ps.length?ps.map(p=>`<article class="provider-card"><div class="provider-card-top">${avatar(p.initial,'avatar-lg')}<button class="icon-btn" data-action="save-provider" data-id="${p.id}" aria-label="${s.savedProviders.includes(p.id)?'Unsave':'Save'} ${p.name}" title="Save provider">${icon(s.savedProviders.includes(p.id)?'check':'plus')}</button></div><h3>${p.name}</h3><span class="provider-specialty">${p.specialty}</span><p>${p.about}</p><div class="tag-row">${p.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="provider-metrics"><span>Sample accepted jobs<strong>${p.reliability}</strong></span><span>Est. recovery<strong>${p.eta}</strong></span></div><div class="provider-card-bottom"><span>Sample quote<strong>${money(p.price)} <small>USDC</small></strong></span><span class="tag">${p.asset?'8004':'CREW'}</span></div><button class="btn btn-outline" data-action="provider-profile" data-id="${p.id}">View profile ${icon('arrow')}</button></article>`).join(''):`<div class="empty-state">${icon('search')}<h3>No matching specialists.</h3><p>Try searching for data, extraction, or validation.</p></div>`}
function detail(s,id){const j=s.jobs.find(j=>j.id===id);if(!j)return `<div class="empty-state">${icon('file')}<h3>Recovery not found.</h3><p>This job may have been removed from your local workspace.</p><a class="btn btn-outline" href="#/app/jobs">Back to recovery jobs</a></div>`;const p=providers.find(p=>p.id===j.provider);const selected=providers.find(p=>p.id===s.selectedProvider)||providers[0];const finished=['Awaiting review','Verified','Accepted'].includes(j.status);const running=j.status==='Recovering';const nComplete=Math.round(j.completed/j.total*40);const original=Math.round((j.originalCompleted??(finished?Math.floor(j.total*.7):j.completed))/j.total*40);return `<div class="detail-breadcrumb"><a href="#/app/jobs">Broken jobs</a>${icon('right')}<span>${esc(j.id)}</span></div><div class="page-heading"><div><div class="eyebrow">${esc(j.id)} · ${esc(j.type).toUpperCase()}</div><h1>${esc(j.title)}</h1><p>Keep what got done. Fix what didn’t.</p></div>${badge(j.status)}</div><div class="detail-layout"><div class="detail-main"><section class="panel"><div class="panel-heading"><h2>Where the agent left off</h2><button class="icon-btn" data-action="export-package" data-id="${esc(j.id)}" aria-label="Export recovery package">${icon('download')}</button></div><div class="panel-body"><div class="detail-progress"><span>${finished?'All done':running?'Patch is working…':'Saved progress'}</span><strong>${j.completed}<small> / ${j.total} units</small></strong></div><div class="detail-chunks" aria-label="${j.completed} of ${j.total} complete">${Array.from({length:40},(_,i)=>`<span class="${i<original?'complete':i<nComplete?'recovered':running?'running':'pending'}"></span>`).join('')}</div><div class="chunk-legend" style="margin-top:12px"><span><i></i>Preserved work</span><span><i class="is-orange"></i>${finished?'Recovered work':`${j.total-j.completed} remaining`}</span></div>${!finished?`<div class="failure-box">${icon('info')}<div><strong>${esc(j.package?.failure?.code||'WORKER_INTERRUPTED')}</strong><p>${esc(j.package?.failure?.message||'The original worker stopped before the remaining work was completed.')}</p></div></div><div class="gary-note">${mood('gary')}<p><strong>The agent’s last words:</strong> “brb”. Its finished rows are saved and won’t be touched.</p></div>`:''}<div class="data-pairs" style="margin-top:25px"><div><span>Job type</span>${esc(j.type)}</div><div><span>Budget cap</span>${money(j.budget)} USDC</div><div><span>Package version</span>v${esc(j.package?.version||'0.1')}</div><div><span>Environment</span>Live</div></div></div></section><section class="panel"><div class="panel-heading"><h2>${finished?'The checks':'How we’ll know it’s done'}</h2><span>${finished?'Verifier':'Agreed up front'}</span></div><div class="panel-body"><div class="validation-list">${[['Required fields present','Schema'],['Expected unit count matches',`${j.total} units`],['Unique record identifiers','No duplicates'],['Completed artifacts preserved','Read-only']].map(([t,label])=>`<div class="validation-row">${icon(finished?'check':'shield')}${t}<span>${label}</span></div>`).join('')}</div></div></section><section class="panel"><div class="panel-heading"><h2>The story so far</h2><span>${s.live?'Job log':'Job log'}</span></div><div class="activity-list">${j.events.map((e,i)=>`<div class="activity-item"><span class="activity-symbol">${icon(e.kind)}</span><div><strong>${esc(e.label)}</strong><p>${esc(e.detail)}</p></div><span>${String(i+1).padStart(2,'0')}</span></div>`).join('')}</div></section></div><aside class="detail-side"><section class="panel"><div class="panel-heading"><h2>${j.status==='Needs rescue'?'Pick a fixer':j.status==='Awaiting review'?'Check the work':j.status==='Accepted'?'Pay the fixer':j.status==='Verified'?'Done, actually':running?'Patch is on it':'Rescue closed'}</h2><span class="tag">${'LIVE'}</span></div><div class="panel-body">${j.status==='Needs rescue'?`<p style="font-size:10px;color:#95a184">Quotes for the leftover rows. Payment waits until you accept.</p>${providers.map(pr=>`<button class="provider-option ${selected.id===pr.id?'selected':''}" data-action="select-provider" data-id="${pr.id}" style="width:100%" aria-pressed="${selected.id===pr.id}">${avatar(pr.initial)}<div style="text-align:left"><strong>${pr.name}</strong><small>${pr.checks}</small></div><span>${money(pr.price)}<small>USDC · ${pr.eta}</small></span></button>`).join('')}<div class="cost-list"><div><span>Provider quote</span><strong>${money(selected.price)}</strong></div><div><span>Platform fee · 5%</span><strong>${money(selected.price*.05)}</strong></div><div class="total"><span>Total · USDC</span><strong>${money(selected.price*1.05)}</strong></div><div><span>Your budget cap</span><strong>${money(j.budget)}</strong></div></div><button class="btn btn-orange" data-action="start-recovery" data-id="${esc(j.id)}" ${selected.price*1.05>j.budget?'disabled':''}>${icon('play')} Send in the fixer</button>${s.live?`<button class="btn btn-outline" style="margin-top:10px" data-action="cancel-job" data-id="${esc(j.id)}">Cancel rescue</button>`:''}${selected.price*1.05>j.budget?'<small style="color:#b66b40">This quote exceeds your budget. Choose another provider or create a job with a higher cap.</small>':`<small>${'Authorize the fixer. USDC moves only after you accept the output.'}</small>`}`:p?`<div class="provider-option selected">${avatar(p.initial)}<div><strong>${p.name}</strong><small>${p.specialty}</small></div>${icon('shield')}</div><div class="cost-list"><div><span>Provider payment</span><strong>${money(j.price)}</strong></div><div><span>Platform fee · 5%</span><strong>${money(j.price*.05)}</strong></div><div class="total"><span>Total · USDC</span><strong>${money(j.price*1.05)}</strong></div></div>${running?`<button class="btn btn-outline" disabled>${icon('refresh')} Patch is working</button><small>This page updates on its own.</small>${s.live?`<button class="btn btn-outline" style="margin-top:10px" data-action="cancel-job" data-id="${esc(j.id)}">Cancel rescue</button>`:''}`:j.status==='Awaiting review'?`${s.live?`<button class="btn btn-outline" style="margin-bottom:10px" data-action="export-result" data-id="${esc(j.id)}">${icon('download')} Download output for review</button>`:''}<button class="btn btn-orange" data-action="accept-recovery" data-id="${esc(j.id)}">${icon('check')} Looks good, accept</button><button class="btn btn-outline" style="margin-top:10px" data-action="reject-recovery" data-id="${esc(j.id)}">Nope, try again</button><small>Accepting does not move USDC.</small>`:j.status==='Accepted'?`<button class="btn btn-orange" data-action="settle-job" data-id="${esc(j.id)}" ${j.paymentPending?'disabled':''}>${icon('receipt')} ${j.paymentPending?'Confirming payment...':`Pay ${money(j.price*1.05)} USDC`}</button><small>${j.paymentPending?'Checking your existing payment. This page updates automatically.':'Acceptance is saved. Payment is next.'}</small>`:j.status==='Verified'?`<a href="#/app/receipts/${esc(j.id)}" class="btn btn-dark">${icon('receipt')} ${'View receipt'}</a><button class="btn btn-outline" style="margin-top:10px" data-action="export-result" data-id="${esc(j.id)}">${icon('download')} Export result</button><small>${j.paymentSignature?esc(j.paymentSignature):'Paid record is on the receipt.'}</small>${s.live&&j.paymentSignature?`<button class="btn btn-outline" style="margin-top:10px" data-action="dispute-job" data-id="${esc(j.id)}">Dispute</button>`:''}`:''}`:`<div><p style="font-size:12px">This recovery has been closed.</p>${s.live&&['Failed','Rejected','Expired'].includes(j.status)?`<button class="btn btn-orange" data-action="retry-job" data-id="${esc(j.id)}">Try again</button>`:''}</div>`}</div></section><section class="panel"><div class="panel-heading"><h2>House rules</h2>${icon('shield')}</div><div class="panel-body"><div class="validation-list"><div class="validation-row">${icon('check')} Fixer only sees the leftovers</div><div class="validation-row">${icon('check')} Can’t spend past your cap</div><div class="validation-row">${icon('check')} Checks agreed before work starts</div></div><p style="font-size:9px;line-height:1.9;margin-top:16px;color:#9da88e">${'The fixer only resumes the remaining chunks. Accepting and paying are separate.'}</p></div></section></aside></div>`}
function receipts(s){const js=s.jobs.filter(j=>['Verified','Accepted','Disputed','Refunded'].includes(j.status));const settlementLabel=j=>j.paymentSignature?'Paid':j.status==='Accepted'?'Unpaid':s.live?j.status:'Live';return `${heading('PROOF IT HAPPENED','Receipts','What got fixed, who fixed it, and what it would have cost.',false)}<div class="panel"><div class="panel-heading"><h2>Finished jobs</h2><span>USDC</span></div>${js.length?`<div class="table-scroll"><table class="job-list"><thead><tr><th>RECOVERY</th><th>PROVIDER</th><th>TOTAL</th><th>SETTLEMENT</th><th></th></tr></thead><tbody>${js.map(j=>`<tr><td><div class="job-title-cell"><span class="mini-job-icon">${icon('receipt')}</span><div><strong>${esc(j.title)}</strong><small>${esc(j.id)}</small></div></div></td><td>${esc(providers.find(p=>p.id===j.provider)?.name||'Specialist')}</td><td class="table-amount" data-label="Budget">${money(j.price*1.05)}<small>USDC</small></td><td><span class="status ${j.paymentSignature?'green':'gray'}">${esc(settlementLabel(j))}</span></td><td><a class="text-link" href="#/app/receipts/${esc(j.id)}" aria-label="View receipt ${esc(j.id)}">${icon('arrow')}</a></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><div class="empty-art">${mood('sleep')}</div><h3>No receipts yet. Patch is napping.</h3><p>Finish a rescue and your receipt shows up here.</p><a href="#/app/jobs" class="btn btn-outline">Find a broken job</a></div>`}</div>`}
function receipt(s,id){const j=s.jobs.find(j=>j.id===id&&['Verified','Accepted','Disputed','Refunded'].includes(j.status));if(!j)return `<div class="empty-state"><h3>No accepted receipt for this job.</h3><a class="btn btn-outline" href="#/app/receipts">Back to receipts</a></div>`;const p=providers.find(p=>p.id===j.provider);return `<div class="detail-breadcrumb"><a href="#/app/receipts">Receipts</a>${icon('right')}<span>${esc(j.id)}</span></div><div class="panel receipt-card"><div class="receipt-success"><div class="receipt-art">${mood('party')}</div><div class="eyebrow" style="justify-content:center;margin-bottom:10px">JOB DONE</div><h2>Fixed. Gary owes Patch one.</h2><p>${esc(j.title)}</p><span class="status gray" style="display:inline-flex;width:auto;height:auto;border-radius:5px;margin:14px 0 0">${esc(j.onChain?'Paid on Solana':j.paymentSignature?'Paid':j.status==='Accepted'?'Accepted, unpaid':j.status)}</span></div><div class="receipt-table"><div><span>Receipt ID</span><strong>${esc(j.paymentSignature||(j.paymentSignature?j.paymentSignature:'Unpaid'))}</strong></div><div><span>Recovery specialist</span><strong>${esc(p?.name||'Specialist')}</strong></div><div><span>Units completed</span><strong>${j.completed} / ${j.total}</strong></div><div><span>Acceptance checks</span><strong>Verifier checks</strong></div><div><span>Provider payment</span><strong>${money(j.price)} USDC</strong></div><div><span>Platform fee · 5%</span><strong>${money(j.price*.05)} USDC</strong></div><div class="receipt-total"><span>${'Total'}</span><strong>${money(j.price*1.05)} USDC</strong></div></div><div class="receipt-actions">${j.status==='Accepted'?`<button class="btn btn-orange" data-action="settle-job" data-id="${esc(j.id)}" ${j.paymentPending?'disabled':''}>Pay ${money(j.price*1.05)} USDC</button>`:''}<button class="btn btn-dark" data-action="export-receipt" data-id="${esc(j.id)}">${icon('download')} ${'Export receipt'}</button><a href="#/app/jobs/${esc(j.id)}" class="btn btn-outline">View recovery ${icon('right')}</a></div></div>`}
function settings(s){return `${heading('YOUR RULES','Settings','Preferences for this workspace. Saved in this browser only.',false)}<div class="settings-grid"><section class="panel"><div class="panel-heading"><h2>Workspace preferences</h2>${icon('user')}</div><div class="panel-body"><form id="settings-form"><label for="workspace-name">Workspace name</label><input id="workspace-name" name="workspace" maxlength="40" required value="${esc(s.workspace||'My workspace')}"><label for="default-budget" style="margin-top:12px">Default recovery budget · USDC</label><input id="default-budget" name="budget" type="number" min="1" max="1000" step="0.01" required value="${s.defaultBudget||10}"><button type="submit" class="btn btn-dark">Save preferences ${icon('check')}</button></form></div></section><section class="panel"><div class="panel-heading"><h2>Your local data</h2>${icon('shield')}</div><div class="panel-body"><p>Preferences stay in this browser. Recovery files stay with your account, and USDC moves only after you accept the output.</p><button class="btn btn-outline" data-action="export-workspace">${icon('download')} Export workspace</button><button class="btn btn-outline" style="display:flex;color:#ad6b43" data-action="reset-workspace">${icon('refresh')} Reset local data</button></div></section></div><div class="notice">${icon('info')}RelayWorks is live. Sign in with your wallet. We will never ask for your private key. Nobody legit ever will.</div>`}
